import re
PROMPT = re.compile(r"^\[[^\]]+\] > ")
FLAGS = re.compile(r"^Flags: (?P<legend>.*\S)\s*$")
FIRST = re.compile(r"^\s*(?P<id>\d+)\s+(?P<flags>[A-Z ]*)\s+(?P<rest>\S.*?)\s*$")
CONT = re.compile(r"^\s+(?P<rest>\S.*?)\s*$")
COMMENT = re.compile(r"^;;; ?(?P<comment>.*)$")
SPLIT = re.compile(r"\s+(?=[\w.-]+=)")

def kvs(text):
    out = {}
    for tok in SPLIT.split(text.strip()):
        if "=" not in tok:
            continue
        k, v = tok.split("=", 1)
        if len(v) >= 2 and v[0] == v[-1] == "\"":
            v = v[1:-1]
        out[k] = v
    return out

def parse(lines):
    skip, legend, legend_lines = [], {}, []
    recs, used = [], []
    cur = None
    for j, ln in enumerate(lines):
        if not ln.strip():
            continue
        if PROMPT.match(ln):
            skip.append(j)
            continue
        m = FLAGS.match(ln)
        if m:
            for part in m.group("legend").split(","):
                if " - " in part:
                    k, v = part.strip().split(" - ", 1)
                    legend[k] = v
            legend_lines.append(j)
            continue
        m = FIRST.match(ln)
        if m:
            cur = {"#": m.group("id"), "flags": m.group("flags").replace(" ", ""), "comment": ""}
            recs.append(cur)
            rest = m.group("rest")
        else:
            m = CONT.match(ln)
            if not m or cur is None:
                continue
            rest = m.group("rest")
        used.append(j)
        c = COMMENT.match(rest)
        if c:
            cur["comment"] = c.group("comment").strip()
        else:
            cur.update(kvs(rest))
    cols = []
    for r in recs:
        for k in r:
            if k not in cols:
                cols.append(k)
    recs = [{k: r.get(k, "") for k in cols} for r in recs]
    blocks = []
    if legend:
        blocks.append({"name": "flags", "kind": "kv", "lines": legend_lines, "records": [legend]})
    blocks.append({"name": "interfaces", "kind": "table", "lines": used, "records": recs})
    return {"blocks": blocks, "skip": skip}
